/**
 * Removing an attachment returns exactly the megabytes it was charged: each
 * file is rounded up to a whole megabyte on upload, so the same rounding is
 * subtracted here. A missing row fails as not found and changes nothing.
 */
export async function removeAttachment(
  actor: Actor,
  input: DeleteAttachmentInput,
): Promise<void> {
  assertOrgScope(actor, input.orgId);

  const attachment = requireFound(
    await attachmentRepo.findAttachmentById(
      input.orgId,
      input.attachmentId as AttachmentId,
    ),
    "Attachment",
    input.attachmentId,
  );

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, attachment.issueId),
    "Issue",
    attachment.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));

  const chargedMb = Math.ceil(attachment.sizeBytes / BYTES_PER_MB);
  await attachmentRepo.deleteAttachment(input.orgId, input.attachmentId);
  await usageRepo.incrementUsage(input.orgId, {
    storageMbUsed: -chargedMb,
  });
}

