// Same charge as an upload: each of this workspace's files, rounded up
// to a whole megabyte, then summed. A single ceil of the byte total (or
// a sum across tenants) would drift from the running counter.
const storage = db
  .select({
    value: sql<number | null>`coalesce(sum((${attachments.sizeBytes} + ${BYTES_PER_MB - 1}) / ${BYTES_PER_MB}), 0)`,
  })
  .from(attachments)
  .where(eq(attachments.orgId, orgId))
  .get();

const next = {
  orgId,
  seatsUsed: seats?.value ?? 0,
  projectsUsed: projectCount?.value ?? 0,
  issuesUsed: issueCount?.value ?? 0,
  storageMbUsed: storage?.value ?? 0,
  measuredAt: toIsoTimestamp(new Date()),
};

